-- Part of the move to neutral built-in texts (src/lib/siteContent.ts): every text «Кең Жылыой»
-- shows today becomes its own saved text, so its site reads exactly as before while a new
-- institution starts from the neutral wording. Keys it has already edited are left alone
-- (on conflict do nothing). The visiting rules are neutral already and stay built in.

insert into public.org_content (organization_id, key, value_kk, value_ru)
select o.id, v.key, v.kk, v.ru
from public.organizations o
cross join (values
  ('hero.eyebrow', 'Атырау облысы, Жылыой ауданы', 'Атырауская область, Жылыойский район'),
